content.text:
{
  "name": "LabOne 通用模块",
  "name_en": "LabOne Generic Module",
  "manufacturer": "Zurich Instruments",
  "description": "这是一个非物理的软件模块组件，用于表示 Zurich Instruments LabOne 中的通用模块接口。它在实验中用于连接 Data Server、订阅或取消订阅节点、启动模块执行、查询进度、等待任务完成，并读取模块返回的数据；适合作为没有专用类时的通用模块控制入口。",
  "description_en": "This is a non-physical software module component representing a generic LabOne module interface from Zurich Instruments. In laboratory workflows, it is used to connect to the Data Server, subscribe or unsubscribe nodes, start module execution, query progress, wait for completion, and read data returned by the module; it serves as a general control entry point when no specialized class is available.",
  "actions": [
    {
      "action_name": "auto-execute",
      "description": "启动模块执行。",
      "description_en": "Start the module execution."
    },
    {
      "action_name": "auto-progress",
      "description": "查询模块当前执行进度。",
      "description_en": "Get the current execution progress of the module."
    },
    {
      "action_name": "auto-read",
      "description": "读取模块返回的数据；若采集仍在进行，可能只返回部分数据。",
      "description_en": "Read data returned by the module; if acquisition is still ongoing, only partial data may be returned."
    },
    {
      "action_name": "auto-subscribe",
      "description": "订阅一个节点，可为模块节点或已连接设备的节点。",
      "description_en": "Subscribe to a node, either from the module itself or from a connected device."
    },
    {
      "action_name": "auto-unsubscribe",
      "description": "取消订阅一个节点，可为模块节点或已连接设备的节点。",
      "description_en": "Unsubscribe from a node, either from the module itself or from a connected device."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待模块执行完成。",
      "description_en": "Wait until the module execution is finished."
    },
    {
      "action_name": "auto-raw_module",
      "description": "获取底层 zhinst.core 模块。",
      "description_en": "Get the underlying zhinst.core module."
    }
  ],
  "tag_hints": [
    "LabOne modules",
    "Zurich Instruments",
    "Data Server session",
    "node subscription",
    "module execution control",
    "progress monitoring",
    "data readout"
  ]
}

